parameters.jsCode:
const abi = $json.abi_information.abi;

let normalisedFunctions = [];

for (const item of abi) {

    // Only analyse callable functions
    if (item.type !== "function") {
        continue;
    }

    if (!item.name) {
        continue;
    }


    const name = item.name.toLowerCase();


    let category = "Metadata / Informational";
    let security_domain = "None";


    // -----------------------------------
    // Upgradeability Detection
    // -----------------------------------
    if (
        name.includes("upgrade") ||
        name.includes("implementation") ||
        name.includes("initialize")
    ) {

        category = "Upgradeability";
        security_domain = "Logic Control";

    }


    // -----------------------------------
    // Governance / Access Control
    // -----------------------------------
    else if (
        name.includes("owner") ||
        name.includes("admin") ||
        name.includes("role") ||
        name.includes("access") ||
        name.includes("permission")
    ) {

        category = "Governance";
        security_domain = "Privileged Access";

    }


    // -----------------------------------
    // External Protocol Dependencies
    // -----------------------------------
    else if (

    name.includes("pool") ||

    name.includes("treasury") ||

    name.includes("controller") ||

    name.includes("comptroller") ||

    name.includes("oracle") ||

    name.includes("underlying") ||

    name.includes("interest") ||

    name.includes("exchange") ||

    name.includes("borrowindex") ||

    name.includes("accrue") ||

    name.includes("cash")

    ) {

        category = "External Dependency";
        security_domain = "Protocol Integration";

    }


    // -----------------------------------
    // Signature / EIP712 Security
    // -----------------------------------
    else if (
        name.includes("permit") ||
        name.includes("nonce") ||
        name.includes("domain") ||
        name.includes("typehash") ||
        name.includes("authorization") ||
        name.includes("signature")
    ) {

        category = "Signature Authorization";
        security_domain = "Meta Transaction Security";

    }


    // -----------------------------------
    // Accounting / Balance Logic
    // -----------------------------------
    else if (
        name.includes("scaled") ||
        name.includes("balance") ||
        name.includes("total")
    ) {

        category = "Accounting Mechanism";
        security_domain = "Balance Calculation";

    }


    // -----------------------------------
    // Asset Configuration
    // -----------------------------------
    else if (
        name.includes("reserve") ||
        name.includes("asset") ||
        name.includes("configuration")
    ) {

        category = "Asset Configuration";
        security_domain = "Protocol Risk Parameters";

    }


    // -----------------------------------
    // Financial Operations
    // -----------------------------------
    else if (

    name.includes("mint") ||

    name.includes("burn") ||

    name.includes("transfer") ||

    name.includes("approve") ||

    name.includes("withdraw") ||

    name.includes("deposit") ||

    name.includes("supply") ||

    name.includes("borrow") ||

    name.includes("repay") ||

    name.includes("liquidat") ||

    name.includes("redeem") ||

    name.includes("seize")
    ) {

        category = "Asset Management";
        security_domain = "Financial Control";

    }



    // -----------------------------------
    // Evidence Generation
    // -----------------------------------

    let evidence_reason = 
        "No specific security evidence identified";


    if (category === "Upgradeability") {

        evidence_reason =
        "Function indicates contract logic upgrade or initialization capability";

    }


    else if (category === "Governance") {

        evidence_reason =
        "Function indicates privileged role or administrative control";

    }


    else if (category === "External Dependency") {

        evidence_reason =
        "Function exposes dependency on another protocol component or external contract";

    }


    else if (category === "Signature Authorization") {

        evidence_reason =
        "Function indicates EIP-712 signature based authorization mechanism";

    }


    else if (category === "Asset Management") {

        evidence_reason =
        "Function controls token movement, creation, destruction, or financial operations";

    }


    else if (category === "Accounting Mechanism") {

        evidence_reason =
        "Function relates to balance calculation or internal accounting logic";

    }


    else if (category === "Asset Configuration") {

        evidence_reason =
        "Function modifies or exposes asset risk configuration parameters";

    }


    else if (category === "Metadata / Informational") {

        evidence_reason =
        "Function provides protocol metadata or constant information";

    }



    normalisedFunctions.push({

        function_name: item.name,

        category: category,

        security_domain: security_domain,

        evidence_reason: evidence_reason

    });

}



return {

    json: {

        module_status: "ABI_NORMALISED",

        normalised_functions: normalisedFunctions

    }

};

const abiString = $json.result;

const abi = JSON.parse(abiString);

return {
  json: {

      module_status: "ABI_ACQUIRED",

    contract_metadata: {
      address: $node["02_Contract_Configuration"].json.contract_address,
      network: $node["02_Contract_Configuration"].json.network,
      chain_id: $node["02_Contract_Configuration"].json.chain_id,
      source: "Etherscan V2"
    },

    abi_information: {
      verified: true,
      abi: abi
    },

    contract_summary: {
      function_count: abi.filter(item => item.type === "function").length,
      event_count: abi.filter(item => item.type === "event").length,
      constructor_present: abi.some(item => item.type === "constructor"),
      fallback_present: abi.some(item => item.type === "fallback"),
      receive_present: abi.some(item => item.type === "receive")
    },

    analysis_ready: true

  }
};

parameters.inputSchema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Smart Contract Security Assessment (Neuro-Symbolic)",
  "description": "Comprehensive architectural security assessment synthesizing architecture reconstruction, runtime validation, historical intelligence, and audit intelligence",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "overall_security_posture",
    "assessment_summary",
    "assessment_limitations",
    "findings"
  ],
  "properties": {
    "overall_security_posture": {
      "type": "string",
      "description": "High-level assessment of the contract's architectural security posture"
    },
    "assessment_summary": {
      "type": "string",
      "description": "Executive summary of key architectural observations and findings"
    },
    "assessment_limitations": {
      "type": "array",
      "description": "Explicit acknowledgment of limitations in the assessment methodology",
      "items": {
        "type": "string"
      },
      "minItems": 1
    },
    "findings": {
      "type": "array",
      "description": "Array of architectural security exposures identified through evidence-driven assessment",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "id",
          "title",
          "severity",
          "finding_category",
          "architectural_characteristic",
          "trust_assumption",
          "potential_failure_mode",
          "risk_assessment",
          "classification_rationale",
          "architecture",
          "foundry",
          "historical",
          "audit",
          "architecture_analysis",
          "foundry_analysis",
          "historical_analysis",
          "audit_analysis",
          "evidence_trace",
          "confidence",
          "missing_evidence",
          "contradictory_evidence"
        ],
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique finding identifier (e.g., F-001, F-002)"
          },
          "title": {
            "type": "string",
            "description": "Concise title of the architectural security exposure"
          },
          "severity": {
            "type": "string",
            "enum": [
              "Critical",
              "High",
              "Medium",
              "Low",
              "Informational"
            ],
            "description": "Potential impact if the trust assumption fails"
          },
          "finding_category": {
            "type": "string",
            "description": "Category of the architectural exposure (e.g., Centralisation, Privilege Concentration, Upgradeability Risk, Oracle Dependency)"
          },
          "architectural_characteristic": {
            "type": "object",
            "description": "The specific architectural pattern or design choice that exists",
            "additionalProperties": false,
            "required": [
              "description",
              "confidence",
              "justification"
            ],
            "properties": {
              "description": {
                "type": "string",
                "description": "What architectural characteristic exists and why it is observable"
              },
              "confidence": {
                "type": "number",
                "minimum": 0,
                "maximum": 1,
                "description": "Confidence that this architectural characteristic has been correctly identified (0.00-1.00)"
              },
              "justification": {
                "type": "string",
                "description": "Why this architectural characteristic is confidently observed from the evidence"
              }
            }
          },
          "trust_assumption": {
            "type": "object",
            "description": "The operational trust dependency required for the architecture to operate safely",
            "additionalProperties": false,
            "required": [
              "description",
              "confidence",
              "justification"
            ],
            "properties": {
              "description": {
                "type": "string",
                "description": "What operational assumption must hold for this architecture to be safe"
              },
              "confidence": {
                "type": "number",
                "minimum": 0,
                "maximum": 1,
                "description": "Confidence that this trust assumption is correctly identified (0.00-1.00)"
              },
              "justification": {
                "type": "string",
                "description": "Why this trust assumption is necessary for safe operation"
              }
            }
          },
          "potential_failure_mode": {
            "type": "object",
            "description": "How the trust assumption could fail",
            "additionalProperties": false,
            "required": [
              "description",
              "confidence",
              "justification"
            ],
            "properties": {
              "description": {
                "type": "string",
                "description": "A plausible scenario in which the trust assumption fails"
              },
              "confidence": {
                "type": "number",
                "minimum": 0,
                "maximum": 1,
                "description": "Confidence that this failure mode is plausible (0.00-1.00)"
              },
              "justification": {
                "type": "string",
                "description": "Why this failure mode is plausible given the architectural design"
              }
            }
          },
          "risk_assessment": {
            "type": "object",
            "description": "The security impact if the failure mode occurs",
            "additionalProperties": false,
            "required": [
              "description",
              "impact",
              "rationale"
            ],
            "properties": {
              "description": {
                "type": "string",
                "description": "What security consequences would result from this failure mode"
              },
              "impact": {
                "type": "string",
                "description": "Scope and magnitude of impact (e.g., protocol compromise, fund loss, privilege escalation)"
              },
              "rationale": {
                "type": "string",
                "description": "Why this failure mode creates this level of security risk"
              }
            }
          },
          "classification_rationale": {
            "type": "object",
            "description": "Evidence-based reasoning for generating this finding",
            "additionalProperties": false,
            "required": [
              "primary_evidence",
              "secondary_evidence",
              "missing_evidence",
              "contradictory_evidence",
              "decision"
            ],
            "properties": {
              "primary_evidence": {
                "type": "string",
                "description": "The most direct evidence supporting this finding"
              },
              "secondary_evidence": {
                "type": "array",
                "description": "Supporting evidence from other sources",
                "items": {
                  "type": "string"
                }
              },
              "missing_evidence": {
                "type": "array",
                "description": "Evidence that would strengthen confidence if available",
                "items": {
                  "type": "string"
                }
              },
              "contradictory_evidence": {
                "type": "array",
                "description": "Evidence that argues against this finding",
                "items": {
                  "type": "string"
                }
              },
              "decision": {
                "type": "string",
                "description": "Reasoning for whether this qualifies as an architectural security exposure"
              }
            }
          },
          "architecture": {
            "type": "object",
            "description": "Evidence from architecture reconstruction",
            "additionalProperties": false,
            "required": [
              "support"
            ],
            "properties": {
              "support": {
                "type": "string",
                "enum": [
                  "FULL",
                  "PARTIAL",
                  "NONE",
                  "CONTRADICTED"
                ],
                "description": "Level of architectural evidence support"
              }
            }
          },
          "foundry": {
            "type": "object",
            "description": "Evidence from runtime validation",
            "additionalProperties": false,
            "required": [
              "support"
            ],
            "properties": {
              "support": {
                "type": "string",
                "enum": [
                  "FULL",
                  "PARTIAL",
                  "NONE",
                  "CONTRADICTED"
                ],
                "description": "Level of runtime validation support"
              },
              "validated_properties": {
                "type": "array",
                "description": "Specific runtime properties that were validated",
                "items": {
                  "type": "string"
                }
              },
              "runtime_observations": {
                "type": "array",
                "description": "Deterministic observations from runtime execution",
                "items": {
                  "type": "string"
                }
              },
              "runtime_limitations": {
                "type": "array",
                "description": "What cannot be validated through runtime checks",
                "items": {
                  "type": "string"
                }
              }
            }
          },
          "historical": {
            "type": "object",
            "description": "Evidence from historical exploit intelligence",
            "additionalProperties": false,
            "required": [
              "support"
            ],
            "properties": {
              "support": {
                "type": "string",
                "enum": [
                  "FULL",
                  "PARTIAL",
                  "NONE",
                  "CONTRADICTED"
                ],
                "description": "Level of historical precedent support"
              },
              "matched_exploit": {
                "type": "string",
                "description": "Historical incident with similar architecture (e.g., Poly Network, Wormhole, Euler)"
              },
              "similarity_score": {
                "type": "number",
                "minimum": 0,
                "maximum": 1,
                "description": "Architectural similarity to the matched incident (0.00-1.00)"
              },
              "shared_characteristics": {
                "type": "array",
                "description": "Architectural characteristics shared with the historical incident",
                "items": {
                  "type": "string"
                }
              },
              "architectural_differences": {
                "type": "array",
                "description": "How the current architecture differs from the historical case",
                "items": {
                  "type": "string"
                }
              },
              "why_relevant": {
                "type": "string",
                "description": "Why this historical precedent is relevant to the current assessment"
              },
              "why_not_identical": {
                "type": "string",
                "description": "Why the current architecture is not identical to the historical incident"
              }
            }
          },
          "audit": {
            "type": "object",
            "description": "Evidence from independent audit intelligence",
            "additionalProperties": false,
            "required": [
              "support"
            ],
            "properties": {
              "support": {
                "type": "string",
                "enum": [
                  "FULL",
                  "PARTIAL",
                  "NONE",
                  "CONTRADICTED"
                ],
                "description": "Level of audit evidence support"
              },
              "audit_coverage": {
                "type": "string",
                "description": "What audit observations are relevant to this architectural characteristic"
              },
              "audit_findings": {
                "type": "array",
                "description": "Specific audit findings relevant to this exposure",
                "items": {
                  "type": "string"
                }
              },
              "audit_gaps": {
                "type": "array",
                "description": "Areas where audit coverage is absent or incomplete",
                "items": {
                  "type": "string"
                }
              }
            }
          },
          "architecture_analysis": {
            "type": "string",
            "description": "REQUIRED: Synthesis of what architecture reconstruction reveals about this observation. Include specific architectural patterns, functions, modifiers, state variables. Explain whether the architecture introduces concentrations of trust or privilege."
          },
          "foundry_analysis": {
            "type": "string",
            "description": "REQUIRED: Synthesis of what runtime validation reveals about this observation. Identify confirmed or contradicted runtime properties. Explain what governance/operational controls cannot be validated by runtime checks."
          },
          "historical_analysis": {
            "type": "string",
            "description": "REQUIRED: Identification of relevant historical exploits (Poly Network, Audius, Harvest, Wormhole, Euler, etc.). For each: explain shared characteristics, differences, relevance, and why not identical. DO NOT claim exploitability based solely on historical similarity."
          },
          "audit_analysis": {
            "type": "string",
            "description": "REQUIRED: Synthesis of what independent audits reveal about this observation. Identify audit findings, mitigations, or gaps. Explain audit coverage and what remains unaddressed. If no coverage, state explicitly."
          },
          "evidence_trace": {
            "type": "array",
            "description": "Direct references to specific architectural facts, runtime observations, historical incidents, or audit findings supporting this assessment",
            "items": {
              "type": "string"
            },
            "minItems": 1
          },
          "confidence": {
            "type": "object",
            "description": "Four confidence dimensions for this assessment",
            "additionalProperties": false,
            "required": [
              "architectural_confidence",
              "deployment_confidence",
              "historical_confidence",
              "assessment_confidence"
            ],
            "properties": {
              "architectural_confidence": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "value",
                  "justification"
                ],
                "properties": {
                  "value": {
                    "type": "number",
                    "minimum": 0,
                    "maximum": 1,
                    "description": "Confidence that the architectural characteristic was correctly identified (0.00-1.00)"
                  },
                  "justification": {
                    "type": "string",
                    "description": "Why this confidence level is appropriate"
                  }
                }
              },
