return {
  protocol,
  chain,
  repository: `C:\\Users\\Sathya\\.n8n-files\\AuditRepository\\${protocol}`,

  metadata: {
    repository_type: "Audit Intelligence Repository",
    evidence_source: "Independent Security Audit Corpus",
    generated_at: new Date().toISOString()
  }
};

// Get the protocol from the resolver
const protocol = $("11_Audit_Repository_Resolver").first().json.protocol;

// Get all audit files
const audits = $input.all();

// Function to convert DD-MM-YYYY from the filename into a Date
function getDate(fileName) {
  const match = fileName.match(/^(\d{2})-(\d{2})-(\d{4})/);

  if (!match) {
    // Files without a leading date are treated as the oldest
    return new Date(0);
  }

  const [, day, month, year] = match;

  return new Date(`${year}-${month}-${day}`);
}

// Sort newest first
audits.sort((a, b) => {
  return getDate(b.json.fileName) - getDate(a.json.fileName);
});

// Select the newest audit
const selected = audits[0];

return {
  protocol,
  selectedAudit: selected.json.fileName,
  selectionPolicy: "Latest audit report",
  auditPath:
    `C:\\Users\\Sathya\\.n8n-files\\AuditRepository\\${protocol}\\${selected.json.fileName}`
};

