/***********************************************************************
 * NODE 08a — FILTER AN OVERSIZED AUDIT DOCUMENT TO RELEVANT SECTIONS
 * COMPOUND VARIANT (v2 -- parses raw HTML directly)
 *
 * v1 of this node assumed the HTTP node would return markdown-style
 * text ("## Severity" / "#### Title" as literal characters), matching
 * the Aave/StErMi source. Confirmed against this run's actual
 * json.data that OpenZeppelin's Compound Audit page is served as raw
 * HTML (<h2>/<h4> tags, full nav/footer chrome, HubSpot boilerplate)
 * -- there is no readable-text conversion happening upstream of this
 * node. So this version parses the HTML tags directly instead of
 * looking for markdown characters.
 *
 * Structural facts about this specific page, confirmed by inspecting
 * the actual fetched HTML:
 *   - The ENTIRE article (intro paragraph through "Summary") sits
 *     inside a single <span id="hs_cos_wrapper_post_body"> block.
 *   - There is no other <h2> anywhere in the page outside that block
 *     (nav/footer use <li>/<a>/<p class="footer-column-title">, not
 *     headings) -- so a global <h2> scan across the whole raw HTML is
 *     safe and does not need the post_body span isolated first.
 *   - Severity sections are <h2>Critical Severity</h2>, <h2>High
 *     Severity</h2>, <h2>Medium Severity</h2>, <h2>Low Severity</h2>,
 *     plus a non-severity <h2>Notes</h2> section that also contains
 *     real findings (Unvetted Token Warning, Transparent Proxy
 *     Pattern), and trailing <h2>Conclusion</h2> / <h2>Summary</h2>
 *     sections that are prose, not findings.
 *   - Individual findings are <h4>Title</h4>. One Low-severity finding
 *     ("cToken Related Issues") further nests <h6> sub-headings
 *     (transferability, ERC20 double-spend, decimals size, zero
 *     address mint/burn, mixing concerns) -- none of those are in this
 *     pipeline's taxonomy, so they are kept as body text under their
 *     parent <h4> rather than split into separate findings.
 ***********************************************************************/

// ---- Configure per audit document ----
const RELEVANCE_KEYWORDS = [
    "reserve",
    "admin",
    "comptroller",
    "interest rate",
    "interest-free",
    "liquidat",
    "underlying",
    "unitroller",
    "proxy",
    "error propagation",
    "truncat"
];

const ALWAYS_INCLUDE_TITLES = [
    "Interest-Free Loans",
    "Counterproductive Incentives",
    "Error Propagation",
    "Admin Must Receive Reserves",
    "Unvetted Token Warning",
    "Transparent Proxy Pattern"
];
const ALWAYS_EXCLUDE_TITLES = [
    "Consider Adding Syntax Highlighting to GitHub Repository",
    "Multiple Contracts Per File",
    "Inconsistent NatSpec Usage",
    "Misleading NatSpec Comments",
    "Change uint to uint256",
    // Only matched the "admin" keyword because it's a substring of
    // "acceptAdmin" -- the actual finding is a pure code-hygiene
    // nitpick about a redundant conditional check, not a real
    // security-relevant claim. Confirmed as a false positive during
    // a dry-run against the real page structure.
    "Superfluous Code in acceptAdmin"
];

// Only these <h2> section titles are treated as containing findings.
// "Conclusion" and "Summary" are prose wrap-up, not findings, and are
// deliberately excluded from finding extraction (their text is still
// available to the Agent via the NOTE block below if useful context).
const FINDING_SECTION_TITLES = /Severity$/i;
const ALSO_TREAT_AS_FINDING_SECTION = ["Notes"];

// ---- Input extraction ----
function getRawText(item) {
    const j = item.json || {};
    const candidates = [j.data, j.body, j.text, j.content];
    for (const c of candidates) {
        if (typeof c === "string" && c.length > 0) return c;
    }
    if (typeof j === "string" && j.length > 0) return j;
    return null;
}

const input = $input.first();
const rawHtml = getRawText(input);
if (!rawHtml) {
    throw new Error(
        "08a_filter_compound_audit: could not find the fetched audit's raw text on the input item. " +
        "Checked json.data / json.body / json.text / json.content. Check the HTTP Request node's " +
        "Response Format setting and adjust getRawText() above to match."
    );
}

// ---- HTML -> plain text helper ----
function htmlToText(html) {
    return html
        .replace(/<(p|li|h[1-6]|div|br)[^>]*>/gi, "\n")
        .replace(/<\/(p|li|h[1-6]|div)>/gi, "\n")
        .replace(/<[^>]+>/g, "")
        .replace(/&nbsp;/gi, " ")
        .replace(/&amp;/gi, "&")
        .replace(/&lt;/gi, "<")
        .replace(/&gt;/gi, ">")
        .replace(/&quot;/gi, '"')
        .replace(/&#39;/gi, "'")
        .replace(/[ \t]+/g, " ")
        .replace(/\n[ \t]*(\n[ \t]*)+/g, "\n\n")
        .trim();
}

function slugify(title) {
    return title.trim().toUpperCase().replace(/[^A-Z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}

// ---- Split into <h2> sections ----
const H2_RE = /<h2[^>]*>([\s\S]*?)<\/h2>/gi;
const h2Matches = [...rawHtml.matchAll(H2_RE)];
if (h2Matches.length === 0) {
    throw new Error(
        "08a_filter_compound_audit: found zero <h2> tags in the fetched document. Either the page " +
        "structure has changed from what was inspected when this node was written, or the HTTP node " +
        "is not returning the raw HTML this parser expects -- check json.data directly before assuming " +
        "the parsing logic is wrong."
    );
}

const h2Sections = h2Matches.map((m, i) => {
    const title = htmlToText(m[1]).trim();
    const start = m.index + m[0].length;
    const end = i + 1 < h2Matches.length ? h2Matches[i + 1].index : rawHtml.length;
    return { title, html: rawHtml.slice(start, end) };
});

const findingSections = h2Sections.filter(
    s => FINDING_SECTION_TITLES.test(s.title) || ALSO_TREAT_AS_FINDING_SECTION.includes(s.title)
);
if (findingSections.length === 0) {
    throw new Error(
        `08a_filter_compound_audit: found ${h2Sections.length} <h2> section(s) (${h2Sections.map(s => s.title).join(", ")}) ` +
        "but none matched the expected severity/Notes section titles. Check FINDING_SECTION_TITLES / " +
        "ALSO_TREAT_AS_FINDING_SECTION against the actual section titles just listed."
    );
}

// ---- Split each finding section into <h4> findings ----
const H4_RE = /<h4[^>]*>([\s\S]*?)<\/h4>/gi;
const allSections = [];
for (const section of findingSections) {
    const h4Matches = [...section.html.matchAll(H4_RE)];
    if (h4Matches.length === 0) {
        // Legitimate for e.g. "Critical Severity" -> "None. 🙂"
        continue;
    }
    for (let j = 0; j < h4Matches.length; j++) {
        const title = htmlToText(h4Matches[j][1]).trim();
        const start = h4Matches[j].index + h4Matches[j][0].length;
        const end = j + 1 < h4Matches.length ? h4Matches[j + 1].index : section.html.length;
        const bodyText = htmlToText(section.html.slice(start, end));
        allSections.push({
            heading_id: `${section.title.toUpperCase().replace(/\s+SEVERITY$/i, "")}-${slugify(title)}`,
            title,
            severity: section.title,
            text: `## ${section.title}\n#### ${title}\n\n${bodyText}`
        });
    }
}

if (allSections.length === 0) {
    throw new Error(
        "08a_filter_compound_audit: found severity/Notes <h2> sections but zero <h4> findings inside " +
        "them. Check the raw HTML structure -- it may differ from what this script expects."
    );
}

// ---- Keep only relevant sections ----
const lowerKeywords = RELEVANCE_KEYWORDS.map(k => k.toLowerCase());
const relevantSections = allSections.filter(s => {
    if (ALWAYS_EXCLUDE_TITLES.includes(s.title)) return false;
    if (ALWAYS_INCLUDE_TITLES.includes(s.title)) return true;
    const lower = s.text.toLowerCase();
    return lowerKeywords.some(k => lower.includes(k));
});

if (relevantSections.length === 0) {
    throw new Error(
        `08a_filter_compound_audit: none of the ${allSections.length} finding sections matched any of ` +
        `the configured RELEVANCE_KEYWORDS (${RELEVANCE_KEYWORDS.join(", ")}). Either widen the keyword ` +
        `list or confirm this document actually covers the intended topic area.`
    );
}

